dispatches.raw_expression:
this.box._request<BrowserContent>("POST", `/v2/box/${this.box.id}/browser/goto`, {
      body: { url, tab: this.id },
      timeout: 60000,
    })

this.box._request<{ data?: unknown }>(
      "POST",
      `/v2/box/${this.box.id}/browser/extract`,
      {
        body: {
          instruction,
          schema: jsonSchema,
          tab: this.id,
          ...(options?.model ? { model: options.model } : {}),
        },
        timeout: 180000,
      },
    )

this.box._request<{ elements?: BrowserObserveResult["elements"] }>(
      "POST",
      `/v2/box/${this.box.id}/browser/observe`,
      {
        body: { instruction, tab: this.id, ...(options?.model ? { model: options.model } : {}) },
        timeout: 180000,
      },
    )

this.box._request<{
      success?: boolean;
      message?: string;
      action_description?: string;
      actions?: BrowserActResult["actions"];
      cache_status?: "HIT" | "MISS";
      input_tokens?: number;
      output_tokens?: number;
    }>("POST", `/v2/box/${this.box.id}/browser/act`, {
      body: { instruction, tab: this.id, ...(options?.model ? { model: options.model } : {}) },
      timeout: 180000,
    })

this.box._request<{
      result?: string;
      data?: unknown;
      completed?: boolean;
      steps?: BrowserRunStep[];
      step_count?: number;
      input_tokens?: number;
      output_tokens?: number;
    }>("POST", `/v2/box/${this.box.id}/browser/run`, {
      body: {
        prompt,
        tab: this.id,
        ...(jsonSchema ? { schema: jsonSchema } : {}),
        ...(options.maxSteps ? { max_steps: options.maxSteps } : {}),
        ...(options.model ? { model: options.model } : {}),
      },
      timeout: 600000,
    })

fetch(`${baseUrl}/v2/box`, {
      method: "DELETE",
      headers,
      body: JSON.stringify({ ids }),
    })

fetch(`${baseUrl}/v2/box/settings/env`, {
      method: "PUT",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify({ env_vars: vars }),
    })

fetch(url, {
      method: "POST",
      headers: fetchHeaders,
      body: fetchBody,
    })

fetch(url, {
      method: "POST",
      headers: fetchHeaders,
      body: fetchBody,
      signal: abortController.signal,
    })

fetch(url, {
      method: "POST",
      headers: fetchHeaders,
      body: fetchBody,
      signal: abortController.signal,
    })

this._request<CodeExecutionResult>("POST", `/v2/box/${this.id}/code`, {
      body: {
        code: options.code,
        language: options.lang,
        ...(options.timeout !== undefined && { timeout: options.timeout }),
        ...(folder ? { folder } : {}),
      },
    })

fetch(url, {
      method: "POST",
      headers: { ...this._headers, "Content-Type": "application/json" },
      body: JSON.stringify({ command: ["sh", "-c", command], ...(folder ? { folder } : {}) }),
    })

fetch(url, {
      method: "POST",
      headers: { ...this._headers, "Content-Type": "application/json" },
      body: JSON.stringify({
        code: options.code,
        language: options.lang,
        ...(options.timeout !== undefined && { timeout: options.timeout }),
        ...(folder ? { folder } : {}),
      }),
    })

this._request("POST", `/v2/box/${this.id}/files/write`, {
      body: { path: resolved, content, ...(encoding && { encoding }) },
    })

fetch(url, {
      method: "POST",
      headers: this._headers,
      body: formData,
    })

this._request<{ id: string; url?: string; title?: string }>(
      "POST",
      `/v2/box/${this.id}/browser/tabs`,
      {
        body: {
          url,
          ...(options?.waitUntil ? { wait_until: options.waitUntil } : {}),
          ...(options?.timeout !== undefined ? { timeout: options.timeout } : {}),
        },
        timeout: operationTimeout === undefined ? 60000 : Math.max(60000, operationTimeout + 5000),
      },
    )

this._request<Record<string, unknown>>(
      "POST",
      `/v2/box/${this.id}/browser/recordings`,
      {
        body: options?.maxDurationSeconds
          ? { max_duration_seconds: options.maxDurationSeconds }
          : {},
        timeout: 60000,
      },
    )

this._request<{
        recordings?: Record<string, unknown>[];
        next_cursor?: string;
      }>("GET", `/v2/box/${this.id}/browser/recordings?${params.toString()}`)

this._request("POST", `/v2/box/${this.id}/git/clone`, {
      body: {
        repo: options.repo,
        branch: options.branch,
        depth: options.depth,
        github_token: this._gitToken,
        ...(folder ? { folder } : {}),
      },
    })

this._request<GitCommitResult>("POST", `/v2/box/${this.id}/git/commit`, {
      body: {
        message: options.message,
        author_name: options.authorName,
        author_email: options.authorEmail,
        ...(folder ? { folder } : {}),
      },
    })

this._request<GitConfig>("PUT", `/v2/box/${this.id}/git-config`, {
      body: {
        git_user_name: options.userName,
        git_user_email: options.userEmail,
      },
    })

this._request<PullRequest>("POST", `/v2/box/${this.id}/git/create-pr`, {
      body: {
        title: options.title,
        body: options.body,
        base: options.base,
        ...(folder ? { folder } : {}),
      },
    })

this._request<PublicURL>("POST", `/v2/box/${this.id}/preview`, {
      body: {
        port,
        ...(options?.bearerToken !== undefined && { bearer_token: options.bearerToken }),
        ...(options?.basicAuth !== undefined && { basic_auth: options.basicAuth }),
      },
    })
